  {
    id: 'full-name',
    name: 'fullName',
    label: 'Full name',
    type: 'text',
    required: true,
    autocomplete: 'name',
    placeholder: 'Jane Smith',
    validate: v => v.trim().length >= 2 ? null : 'Please enter your full name.',
  },
  {
    id: 'email',
    name: 'email',
    label: 'Email address',
    type: 'email',
    required: true,
    autocomplete: 'email',
    placeholder: 'jane@example.com',
    validate: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim())
