    name: 'phone',
    label: 'Phone number',
    type: 'tel',
    required: false,
    autocomplete: 'tel',
    placeholder: '+1 (555) 000-0000',
    helperText: 'Optional. Include country code, e.g. +1 (555) 000-0000.',
    validate: v => {
      if (!v.trim()) return null; // optional
      return /^\+?[\d\s\-().]{7,20}$/.test(v.trim())
