    submitBtn.disabled = true;
    submitBtn.textContent = 'Sending…';

    setTimeout(() => {
      status.className = 'success';
      status.textContent = '✓ Your message has been sent. We'll be in touch soon!';
      status.style.display = 'block';
      form.reset();
