        f.input.removeAttribute('aria-invalid');
        f.errorEl.classList.remove('visible');
        f.errorEl.textContent = '';
      });
      submitted = false;
      submitBtn.disabled = false;
      submitBtn.textContent = 'Send message';
      status.focus();
    }, 800);
  });

  return form;
}

