    validate: v => {
      if (!v.trim()) return null; // optional
      return /^\+?[\d\s\-().]{7,20}$/.test(v.trim())
        ? null
        : 'Please enter a valid phone number (e.g. +1 555 000-0000).';
    },
  },
];

/** ── FormField component ─────────────────────────────────────── */
function FormField(spec) {
  const errorId = `${spec.id}-error`;
  const helperId = spec.helperText ? `${spec.id}-helper` : null;
  const describedBy = [helperId, errorId].filter(Boolean).join(' ');

  const label = el('label', { htmlFor: spec.id });
  label.textContent = spec.label;

  if (spec.required) {
    const star = el('span', { 'aria-hidden': 'true', className: 'req-star' }, ' *');
    label.append(star);
  } else {
    const opt = el('span', { className: 'label-optional' }, '(optional)');
    label.append(opt);
  }

  const input = el('input', {
    type: spec.type,
    id: spec.id,
    name: spec.name,
    autocomplete: spec.autocomplete,
    placeholder: spec.placeholder,
    'aria-describedby': describedBy,
    ...(spec.required ? { required: '' } : {}),
  });

  const errorEl = el('span', {
    id: errorId,
    className: 'error-text',
    role: 'alert',
    'aria-live': 'polite',
  });

  const children = [label, input];

  if (spec.helperText) {
    children.push(el('span', { id: helperId, className: 'helper-text' }, spec.helperText));
  }

  children.push(errorEl);

  const wrapper = el('div', { className: 'form-field' }, ...children);

  return { wrapper, input, errorEl, spec };
}

/** ── ContactForm component ──────────────────────────────────── */
function ContactForm() {
  let submitted = false;
  const fields = FIELDS.map(FormField);

  // ── Validation helpers ──────────────────────────────────────
  const validateField = ({ input, errorEl, spec }) => {
    const msg = spec.validate(input.value);
    if (msg) {
      input.setAttribute('aria-invalid', 'true');
      errorEl.textContent = msg;
      errorEl.classList.add('visible');
    } else {
      input.setAttribute('aria-invalid', 'false');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
    return msg;
  };

  // Live-validate on blur only after the form has been submitted once
  fields.forEach(f => {
    f.input.addEventListener('blur', () => {
      if (submitted) validateField(f);
    });
    f.input.addEventListener('input', () => {
      if (submitted) validateField(f);
