  // ── Submit button ────────────────────────────────────────────
  const submitBtn = el('button', {
    type: 'submit',
    className: 'btn-submit',
  }, 'Send message');

  const actions = el('div', { className: 'form-actions' }, submitBtn);
  form.append(actions);

  // ── Submit handler ───────────────────────────────────────────
  form.addEventListener('submit', e => {
    e.preventDefault();
    submitted = true;

    status.className = '';
    status.textContent = '';
    status.style.display = 'none';

    const errors = fields.map(validateField).filter(Boolean);

    if (errors.length > 0) {
      // Focus the first invalid input
      const firstInvalid = fields.find(f => f.input.getAttribute('aria-invalid') === 'true');
      firstInvalid?.input.focus();

      status.className = 'error-summary';
      status.textContent = `Please fix ${errors.length} error${errors.length > 1 ? 's' : ''} before submitting.`;
      status.style.display = 'block';
      return;
    }

    // Success — simulate submission
    submitBtn.disabled = true;
    submitBtn.textContent = 'Sending…';

    setTimeout(() => {
      status.className = 'success';
      status.textContent = '\u2713 Your message has been sent. We\u2019ll be in touch soon!';
      status.style.display = 'block';
      form.reset();
      fields.forEach(f => {
        f.input.removeAttribute('aria-invalid');
        f.errorEl.classList.remove('visible');
        f.errorEl.textContent = '';
      });
