      submitBtn.disabled = false;
      submitBtn.textContent = 'Send message';
      status.focus();
    }, 800);
  });

  return form;
}

/** ── SupportPage component ──────────────────────────────────── */
function SupportPage() {
  const header = el('header', { className: 'card-header' },
    el('h1', {}, 'Contact Support'),
    el('p', {}, 'Fill out the form below and our team will get back to you within one business day.'),
  );

