    'Fields marked ',
    el('span', { className: 'req-star', 'aria-label': 'required' }, '*'),
    ' are required.',
  );

  const card = el('div', { className: 'card' }, header, legend, ContactForm());
  return card;
}

/** ── Mount ──────────────────────────────────────────────────── */
document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('app-root');
  if (root) root.appendChild(SupportPage());
});
